return ['domain'=>'zinn-translate','plural-forms'=>'nplurals=3; plural=(n%10==1 && n%100!=11 ? 0 : n%10>=2 && n%10<=4 && (n%100<10 || n%100>=20) ? 1 : 2);','language'=>'hr','project-id-version'=>'zinn-translate','pot-creation-date'=>'2026-09-08T20:38:11+00:00','po-revision-date'=>'2026-09-08T20:38:11+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Translate'=>'Zinn® Translate','https://zinndigital.com/wordpress-plugins/zinn-translate'=>'https://zinndigital.com/wordpress-plugins/zinn-translate','Publishes this site in every language you choose, on its own web addresses, with translated slugs, metadata, menus, WooCommerce products, hreflang, per-language sitemaps and llms.txt. Translate with your Zinn Digital® plan or with your own provider key.'=>'Objavljuje ovu web-lokaciju na svakom jeziku koji odaberete, na vlastitim web-adresama, s prevedenim adresama, metapodacima, izbornicima, WooCommerce proizvodima, hreflang oznakama, kartama web-lokacije za svaki jezik i llms.txt datotekom. Prevodite uz svoj Zinn Digital® paket ili s ključem vlastitog pružatelja usluga.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','Stored. Type a new value to replace it.'=>'Pohranjeno. Unesite novu vrijednost kako biste je zamijenili.','Filter this list…'=>'Filtriraj ovaj popis…','Filter this list'=>'Filtriraj ovaj popis','Nothing matches that filter.'=>'Ništa ne odgovara tom filteru.','Add a row'=>'Dodaj redak','Remove this row'=>'Ukloni ovaj red','Remove'=>'Ukloni','Zinn Digital®'=>'Zinn Digital®','Zinn Digital® — overview'=>'Zinn Digital® — pregled','Overview'=>'Pregled','Every Zinn® plugin on this site, and whether it is working.'=>'Svaki Zinn® dodatak na ovoj stranici i radi li on.','No connection is needed for this plugin.'=>'Za ovaj dodatak nije potrebna nikakva veza.','Open settings'=>'Otvori postavke','You do not have permission to change these settings.'=>'Nemate dopuštenje za promjenu ovih postavki.','Settings sections'=>'Odjeljci postavki','Support'=>'Podrška','Save changes'=>'Spremi promjene','Tools'=>'Alati','Export settings'=>'Izvoz postavki','Reset to defaults'=>'Vrati na zadano','This puts every setting on this plugin back to its default. Continue?'=>'Ovo vraća svaku postavku ovog dodatka na zadane vrijednosti. Nastaviti?','Diagnostics for support'=>'Dijagnostika za podršku','Import a settings file'=>'Uvezi datoteku s postavkama','Import'=>'Uvezi','Exported files never contain passwords, tokens or API keys — you will need to enter those again on the new site.'=>'Izvezene datoteke nikada ne sadrže lozinke, tokenâ ni API ključeve – morat ćete ih ponovno unijeti na novoj web-lokaciji.','Settings saved.'=>'Postavke su spremljene.','Every setting on this plugin is back to its default.'=>'Sve postavke na ovom doduše vraćene su na zadane vrijednosti.','Done.'=>'Gotovo.','That action is not available.'=>'Ta radnja nije dostupna.','That file could not be read. Choose a settings file exported from a Zinn® plugin.'=>'Datoteku nije moguće pročitati. Odaberite datoteku postavki izvezenu iz Zinn® priključka.','That file is too large to be a settings export.'=>'Ta je datoteka prevelika da bi bila izvoz postavki.','That file is not a Zinn® settings export.'=>'Ta datoteka nije izvoz postavki za Zinn®.','That file was exported from a different plugin (%s), so importing it here would store settings this plugin does not understand.'=>'Ta je datoteka izvezena iz drugog dodatka (%s), pa bi njen uvoz ovdje pohranio postavke koje ovaj dodatak ne prepoznaje.','%d setting imported. Passwords and API keys are never in an export, so enter those again.'=>'Uvezen je %d postavk. Lozinke i API ključevi se nikada ne izvoze, stoga ih unesite ponovno.' . "\0" . '%d postavki je uvezeno. Zaporke i API ključevi nikada nisu uključeni u izvoz, stoga ih ponovo unesite.' . "\0" . '%d postavki je uvezeno. Zaporke i API ključevi nikada nisu uključeni u izvoz, stoga ih ponovo unesite.','Translate'=>'Prevedi','Manual overrides'=>'Ručne prilagodbe','Sitemaps and URLs'=>'Sikempe i URL-ovi','General'=>'Općenito','Who pays for the translation'=>'Tko plaća prijevod','Either your Zinn Digital® plan, or an API key of your own. There is no free tier — somebody pays a provider for every word.'=>'Ili vaš Zinn Digital® plan ili vaš vlastiti API ključ. Ne postoji besplatna razina — netko plaća pružatelju usluge za svaku riječ.','My Zinn Digital® plan'=>'Moj Zinn Digital® paket','My own provider key'=>'Moj vlastiti ključ davatelja usluge','Site ID'=>'ID web-mjesta','From your Zinn Digital® dashboard, on this site\'s Translation tab.'=>'Iz nadzorne ploče Zinn Digital®, na kartici Prijevod ove web-lokacije.','Site token'=>'Token web-mjesta','Provider'=>'Pružatelj usluga','API key'=>'API ključ','Your key, billed to you by the provider. It is stored on this site and sent only to them.'=>'Vaš ključ koji vam naplaćuje pružatelj usluge. Pohranjen je na ovoj stranici i šalje se samo njima.','Model'=>'Model','Leave empty for the cheapest model that does the job well.'=>'Ostavite prazno za najjeftiniji model koji dobro obavlja posao.','This site is written in'=>'Ova je stranica napisana na','Leave empty to use the site language from WordPress settings.'=>'Ostavite prazno za korištenje jezika stranice iz postavki za WordPress.','Languages to publish'=>'Jezici za objavu','Each one gets its own web addresses and its own sitemap. Publish only the languages you want indexed.'=>'Svaka dobiva vlastite web adrese i vlastitu kartu web-lokacije. Objavite samo one jezike koje želite indeksirati.','Translate automatically when I publish or update'=>'Prevedi automatski kada objavim ili ažuriram','Editing a page marks its translations out of date and they are remade in the background. Editing without changing any words costs nothing.'=>'Uređivanje stranice označava njezine prijevode zastarjelima i oni se ponovno izrađuju u pozadini. Uređivanje bez mijenjanja riječi ne košta ništa.','What gets translated'=>'Što se prevodi','Post types'=>'Vrste postova','Translate the web addresses too'=>'Prevedite i web adrese','French visitors get /fr/a-propos/ rather than /fr/about/. The untranslated address keeps working and redirects, so nothing that was indexed breaks.'=>'Francuski posjetitelji dobivaju /fr/a-propos/ umjesto /fr/about/. Netraducirana adresa nastavlja raditi i preusmjerava, tako da se ništa što je bilo indeksirano ne ruši.','Translate SEO titles, descriptions and image alt text'=>'Prevedite SEO naslove, opise i alt tekst slika','Translate categories and tags'=>'Prevedi kategorije i oznake','Translate navigation menus'=>'Prevedi navigacijske izbornike','Translate WooCommerce products and attributes'=>'Prevedite WooCommerce proizvode i atribute','Short descriptions, purchase notes, attribute labels and variation descriptions. Prices, SKUs and stored option values are never touched.'=>'Kratki opisi, bilješke uz kupnju, oznake atributa i opisi varijanti. Cijene, SKU-ovi i spremljene vrijednosti opcija nikada se ne mijenjaju.','SEO'=>'SEO','Add hreflang tags'=>'Dodaj hreflang oznake','Tells search engines these pages are the same page in different languages. Leave this on unless another plugin is already doing it.'=>'Govori tražilicama da su ove stranice ista stranica na različitim jezicima. Ostavite ovo uključeno osim ako to već ne radi neki drugi dodatak.','Publish a sitemap for each language'=>'Objavite kartu web-lokacije za svaki jezik','Publish llms.txt for each language'=>'Objavi llms.txt za svaki jezik','A plain-text map of the site that AI answer engines read. They often cannot run JavaScript and may never fetch a sitemap.'=>'Karta web-mjesta u običnom tekstu koju čitaju AI tražilice. One često ne mogu pokretati JavaScript i možda nikada neće dohvatiti sitemap.','Language switcher'=>'Jezični prebacivač','Style'=>'Stil','Colours, spacing and corners are on the Styling tab. Place it with the block, the [zinn_language_switcher] shortcode, or a menu.'=>'Boje, razmaci i rubovi nalaze se na kartici Stiliziranje. Postavite ga s blokom, kratkim kodom [zinn_language_switcher] ili izbornikom.','Show only these languages'=>'Prikaži samo ove jezike','Leave empty to show every language you publish.'=>'Ostavite prazno za prikaz svih jezika koje objavljujete.','Name each language in its own language'=>'Nazovite svaki jezik na njegovom vlastitom jeziku','Deutsch rather than German. Somebody who cannot read the current page cannot read "German" either.'=>'Deutsch umjesto German. Netko tko ne može čitati trenutnu stranicu ne može čitati ni „German”.','Show flags'=>'Prikaži zastavice','Off by default: a language is not a country, and Arabic and Spanish have no single flag that does not exclude most of their speakers.'=>'Isključeno prema zadanim postavkama: jezik nije država, a arapski i španjolski nemaju jednu zastavu koja ne isključuje većinu njihovih govornika.','Include the language being read'=>'Uključi jezik koji se čita','Include the original language'=>'Uključi izvorni jezik','Add it to this menu'=>'Dodajte ga u ovaj izbornik','Only the menu you name here. Nothing is added to any other menu on the site.'=>'Samo izbornik koji ovdje navedete. Ništa se ne dodaje nijednom drugom izborniku na web-mjestu.','Accent'=>'Naglasak','Background'=>'Pozadina','Text'=>'Tekst','Corner radius'=>'Radijus zaobljenja ruba','Spacing'=>'Razmak','Text size'=>'Veličina teksta','Do not add it to a menu'=>'Nemojte ga dodati u izbornik','Edit any translation here. An edited translation is kept exactly as you wrote it and is never overwritten when the page is translated again.'=>'Ovdje uredite bilo koji prijevod. Uređeni prijevod zadržava se točno onako kako ste ga napisali i nikada se ne prepisuje kada se stranica ponovno prevodi.','Every language'=>'Svaki jezik','Search translations'=>'Pretraži prijevode','Filter'=>'Filtriraj','Content'=>'Sadržaj','Language'=>'Jezik','Translation'=>'Prijevod','Status'=>'Status','Save'=>'Spremi','Nothing translated yet. Publish a language and translation starts in the background.'=>'Ništa još nije prevedeno. Objavite jezik i prijevod će započeti u pozadini.','These addresses are live. Open any of them to check it, and submit the sitemap index to Google Search Console.'=>'Ove su adrese aktivne. Otvorite bilo koju od njih kako biste je provjerili i pošaljite indeks sitemapa u Google Search Console.','You are not allowed to edit translations on this site.'=>'Nije vam dopušteno uređivanje prijevoda na ovoj stranici.','Edited by you — kept'=>'Uredili ste vi — sačuvano','Source changed — will be redone'=>'Izvor je promijenjen — bit će ponovljeno','Up to date'=>'Ažurno','Connected'=>'Povezano','Connecting…'=>'Povezivanje…','Connected, but something needs attention'=>'Povezano, ali nešto zahtijeva pažnju','Not connected'=>'Nije povezano','Running on your own account'=>'Radi na vašem računu','We could not check this'=>'Nismo mogli ovo provjeriti','This plugin did not say why. Send a diagnostics report and we will look.'=>'Ovaj dodatak nije naveo razlog. Pošaljite dijagnostičko izvješće i mi ćemo ga pregledati.','Connection status'=>'Status veze','Last checked %s ago.'=>'Posljednja provjera prije %s.','(opens in a new tab)'=>'(otvara se u novoj kartici)','Send this to Zinn® support'=>'Pošaljite ovo Zinn® podršci','This is exactly what will be sent — nothing else, and nothing hidden. Your passwords, tokens and API keys are not in it.'=>'To je točno ono što će biti poslano — ništa drugo i ništa skriveno. Vaše lozinke, tokeni i API ključevi nisu uključeni u to.','The diagnostics report that will be sent'=>'Dijagnostičko izvješće koje će biti poslano','Copy to clipboard'=>'Kopiraj u međuspremnik','Send this report to Zinn® support'=>'Pošaljite ovo izvješće Zinn® podršci','We open a support ticket for you and reply by email. If you would rather not send it, copy it above and paste it into a ticket yourself.'=>'Otvaramo vam zahtjev za podršku i odgovaramo putem e-pošte. Ako ga radije ne biste poslali, kopirajte ga iznad i sami ga zalijepite u zahtjev.','Copied'=>'Kopirano','We could not reach Zinn Digital® from this server (%s). Copy the report above and open a ticket instead — nothing about your settings is wrong.'=>'Nismo mogli doći do Zinn Digital® s ovog poslužitelja (%s). Kopirajte gore navedeno izvješće i umjesto toga otvorite zahtjev — s vašim postavkama nije ništa u redu.','Sent. Zinn® support has your report and will reply by email.'=>'Podrška za Zinn® primila je vaše izvješće i odgovorit će vam putem e-pošte.','Sent. Zinn® support has your report — reference %s — and will reply by email.'=>'Podrška za Zinn® primila je vaše izvješće — referenca %s — i odgovorit će vam putem e-pošte.','You have sent several reports in a short time. Wait a few minutes and try again — the earlier ones did arrive.'=>'Poslali ste nekoliko izvješća u kratkom vremenu. Pričekajte nekoliko minuta i pokušajte ponovno – prethodna su stigla.','Zinn Digital® could not accept the report just now — that is our end, not yours. Try again shortly, or copy the report above into a ticket.'=>'Zinn Digital® trenutno nije mogao prihvatiti izvještaj — problem je s naše strane, ne s vaše. Pokušajte ponovno uskoro ili kopirajte gornji izvještaj u tiket.','The report was refused (HTTP %d). Copy it above and open a ticket, quoting that number.'=>'Izvješće je odbijeno (HTTP %d). Kopirajte ga gore i otvorite zahtjev s navedenim brojem.','%s — guides and services'=>'%s — vodiči i usluge','User guides'=>'Korisnički vodiči','Read the %s user guide'=>'Pročitajte korisnički priručnik za %s','Hide this'=>'Sakrij ovo','Zinn® hosting for WordPress'=>'Zinn® hosting za WordPress','LiteSpeed, daily backups, free migration and a control panel built for people who run more than one site.'=>'LiteSpeed, dnevne sigurnosne kopije, besplatna migracija i upravljačka ploča prilagođena osobama koje vode više web-mjesta.','The Zinn® marketplace'=>'Zinn® tržnica','Buy and sell established sites, domains and link placements, with the money held safely until both sides are happy.'=>'Kupujte i prodajite postojeće stranice, domene i postavljanja poveznica, uz sigurno čuvanje novca dok obje strane ne budu zadovoljne.','Zinn Hub® — hire people who do this for a living'=>'Zinn Hub® — zaposlite profesionalce koji se time bave','Our global freelance marketplace: browse over 10,000 ready-made services from writers, designers, developers and SEOs, or post a project and let them bid.'=>'Naše globalno tržište neovisnih stručnjaka: pregledajte više od 10.000 gotovih usluga pisaca, dizajnera, programera i SEO stručnjaka ili objavite projekt i dopustite im da daju ponude.','The API key was rejected. Check that it is still valid and has translation access, then save it again.'=>'API ključ je odbijen. Provjerite je li još uvijek valjan i ima li pristup prevođenju, a zatim ga ponovno spremite.','The provider refused on billing or quota. Nothing was translated. Check the balance and limits on your account with them.'=>'Pružatelj usluge je odbio zbog naplate ili kvote. Ništa nije prevedeno. Provjerite stanje i ograničenja na svom računu kod njih.','The translation provider is having a problem at their end. Nothing was translated or charged, and it will try again on the next pass.'=>'Davatelj usluge prevođenja ima problema na svojoj strani. Ništa nije prevedeno ni naplaćeno, a sustav će pokušati ponovno u sljedećem prolazu.','The translation request failed and we could not tell why. Nothing was saved.'=>'Zahtjev za prijevod nije uspio i nismo mogli utvrditi zašto. Ništa nije spremljeno.','Sitemap index'=>'Indeks web-lokacije','%s sitemap'=>'%s sitemap','LLM content map'=>'Karta sadržaja LLM-a','%s LLM content map'=>'%s karta sadržaja LLM-a','Languages published'=>'Objavljeni jezici','Site language'=>'Jezik web-mjesta','SEO plugin'=>'SEO dodatak','No translation provider is set up yet.'=>'Još nije postavljen nijedan pružatelj usluge prevođenja.','Paste an API key from your chosen provider, or connect the site to a Zinn Digital® account, and translation starts on the next pass.'=>'Zalijepite API ključ od odabranog davatelja usluga ili povežite web-mjesto s računom za Zinn Digital® i prijevod počinje u sljedećem prolazu.','Translating with your own %s key.'=>'Prevođenje s vašim vlastitim %s ključem.','This site is not connected to a Zinn Digital® account, which is fine — your provider bills you directly.'=>'Ova stranica nije povezana sa Zinn Digital® računom, što je u redu — vaš vam pružatelj usluga naplaćuje izravno.','Not connected to Zinn Digital® yet.'=>'Još niste povezani s platformom Zinn Digital®.','Add this site\'s ID and token from your Zinn Digital® dashboard, or switch to your own provider key to run without an account.'=>'Dodajte ID i token ove web-lokacije sa svoje nadzorne ploče za Zinn Digital® ili pređite na vlastiti ključ davatelja usluga za rad bez računa.','Connected to Zinn Digital®.'=>'Povezano s platformom Zinn Digital®.','The translation provider is having a problem.'=>'Pružatelj usluge prevođenja ima problema.','Translation is paused — your provider needs attention.'=>'Prijevod je pauziran — vaš pružatelj usluga zahtijeva pažnju.','Translation has not been set up yet.'=>'Prijevod još nije postavljen.','Something went wrong at our end.'=>'Došlo je do pogreške s naše strane.','Check their status page'=>'Provjerite njihovu stranicu sa statusom','Fix this on your account'=>'Ispravite ovo na svom računu','Style preset'=>'Predefinirani stil','A starting point. Anything below overrides it.'=>'Početna točka. Sve ispod toga ima prednost.','Use my own colours and sizes'=>'Koristi moje vlastite boje i veličine','Leave this off and the preset is used exactly as it is.'=>'Isključite ovo i predložak se koristi točno onakav kakav jest.','Zinn® language switcher'=>'Jezični izbornik za Zinn®','Let visitors read this page in another language.'=>'Omogućite posjetiteljima čitanje ove stranice na drugom jeziku.','Title'=>'Naslov','Use the plugin setting'=>'Upotrijebi postavku dodatka','Dropdown'=>'Padajući izbornik','Inline list'=>'Ugrađeni popis','Pills'=>'Kapsule','Minimal text'=>'Minimalni tekst','Flags and names'=>'Oznake i nazivi','Stacked list'=>'Složeni popis','Choose a language'=>'Odaberite jezik','See the Zinn Digital® release notes.'=>'Pogledajte bilješke o izdanju Zinn Digital®.','The downloaded update failed its integrity check and was not installed.'=>'Preuzeto ažuriranje nije prošlo provjeru integriteta i nije instalirano.','No DeepL API key is saved, so there is nothing to translate with.'=>'Nije spremljen nijedan DeepL API ključ, tako da nema ničega za prevođenje.','DeepL does not translate into %s. Choose Google Gemini or OpenAI for this language, or connect the site to Zinn Digital®.'=>'DeepL ne prevodi na %s. Odaberite Google Gemini ili OpenAI za ovaj jezik ili povežite web-mjesto sa Zinn Digital®-om.','DeepL could not be reached. Nothing was translated and nothing was charged; it will try again on the next pass.'=>'Nije moguće uspostaviti vezu s uslugom DeepL. Ništa nije prevedeno niti naplaćeno; sustav će ponovno pokušati u sljedećem prolazu.','Your DeepL character quota is used up for this period. Translation resumes when it resets, or when you raise the limit on your DeepL account.'=>'Vaša kvota znakova za DeepL iskorištena je za ovo razdoblje. Prevođenje se nastavlja kada se ona obnovi ili kada povećate ograničenje na svom DeepL računu.','DeepL answered with something we could not read. Nothing was saved.'=>'DeepL je odgovorio s nečim što nismo mogli pročitati. Ništa nije spremljeno.','No Google Gemini API key is saved, so there is nothing to translate with.'=>'Nije spremljen nijedan Google Gemini API ključ, tako da nema ničega s čime bi se moglo prevoditi.','Google Gemini could not be reached. Nothing was translated and nothing was charged; it will try again on the next pass.'=>'Google Gemini nije dostupan. Ništa nije prevedeno i ništa nije naplaćeno; ponovno će pokušati u sljedećem prolazu.','No OpenAI API key is saved, so there is nothing to translate with.'=>'Nije spremljen nijedan OpenAI API ključ, tako da nema ničega za prevođenje.','OpenAI could not be reached. Nothing was translated and nothing was charged; it will try again on the next pass.'=>'Nije se moglo stupiti u kontakt s platformom OpenAI. Ništa nije prevedeno i ništa nije naplaćeno; sustav će ponovno pokušati u sljedećem prolazu.','This site is not connected to Zinn Digital®, so there is nothing to collect. Add the Site ID and token, or switch to your own provider key.'=>'Ova stranica nije povezana sa Zinn Digital®, tako da nema ništa za prikupiti. Dodajte ID stranice i token ili pređite na vlastiti ključ pružatelja usluga.','This site is not connected to Zinn Digital®.'=>'Ova stranica nije povezana sa Zinn Digital®.','Zinn Digital® could not be reached. Nothing was sent; it will try again on the next pass.'=>'Zinn Digital® nije moguće kontaktirati. Ništa nije poslano; pokušat će ponovno u sljedećem ciklusu.','Translation is paused on this site. Check the account is up to date on your Zinn Digital® dashboard.'=>'Prijevod je pauziran na ovoj web-lokaciji. Provjerite je li račun ažuriran na vašoj nadzornoj ploči za Zinn Digital®.','Zinn Digital® rejected this site\'s token. Copy it again from the site\'s Translation tab on your dashboard.'=>'Zinn Digital® je odbio token ove stranice. Kopirajte ga ponovno s kartice za prijevođenje na nadzornoj ploči stranice.','Zinn Digital® could not be reached. Your site keeps serving the translations it already has.'=>'Zinn Digital® nije bio dostupan. Vaša stranica nastavlja posluživati već postojeće prijevode.','Zinn Digital® answered with something we could not read. Your site keeps serving the translations it already has.'=>'Zinn Digital® je odgovorio nečim što nismo mogli pročitati. Vaša stranica nastavlja isživati ​​već postojeće prijevode.']];